(() => {
'use strict';
const $=s=>document.querySelector(s), svg=$('#history-chart'), tip=$('#tooltip');
const seed={2024:[1800,-2600,3400,-1200,2800,900,-1700,4100,2300,-800,0,0],2025:[-3100,2400,-1800,5100,3600,-900,4200,-2100,3200,1500,0,0],2026:[8200,0,-4200,6600,3100,-1700,5200,2800,-2600,4800]};
const records=Object.entries(seed).flatMap(([year,values])=>values.map((net,i)=>({date:`${year}-${String(i+1).padStart(2,'0')}`,year,net,rounds:net===0?1:i%3+1,wins:net>0?1:0,fees:64*(net===0?1:i%3+1)})));
const state={year:'2026',pending:'2026',metric:'net',fixture:'normal',hover:null,fixed:false};
let timer,geom;
const amount=n=>n==null?'—':new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const signed=n=>n==null?'—':(n>0?'+':'')+amount(n);
const compact=n=>n==null?'—':Math.abs(n)>=1e8?(n>0?'+':'')+(n/1e8).toFixed(2)+'亿':Math.abs(n)>=1e4?(n>0?'+':'')+(n/1e4).toFixed(2)+'万':signed(n);
function aggregate(year){const rs=records.filter(r=>year==='all'||year==='2024-2026'||r.year===year);if(/^\d{4}$/.test(year))return rs.map(r=>({...r}));const groups={};for(const r of rs){const g=groups[r.year]??={date:r.year,net:0,rounds:0,wins:0,fees:0};for(const k of ['net','rounds','wins','fees'])g[k]+=r[k];}return Object.values(groups);}
function rows(){let rs=aggregate(state.year);if(state.fixture==='future'&&state.year==='2026')rs.push(...['2026-11','2026-12'].map(date=>({date,net:null,rounds:null,wins:null,fees:null,status:'future'})));if(state.fixture==='extreme')rs=rs.map(r=>({...r,net:r.net*100000,fees:r.fees*1000}));if(state.fixture==='empty')return rs.map(r=>({...r,net:0,rounds:0,wins:0,fees:0,status:'empty'}));if(state.fixture==='zero')return rs.map(r=>({...r,net:0,wins:0}));if(state.fixture==='missing'){let i=Math.floor(rs.length/2);rs[i]={...rs[i],net:null,rounds:null,wins:null,fees:null,status:'missing'};}return rs;}
function series(rs){let cumulative=0,unknown=false;return rs.map(r=>{if(r.status==='missing')unknown=true;if(r.net!=null)cumulative+=r.net;let cum=unknown||r.status==='future'?null:cumulative;let value=state.metric==='net'?r.net:state.metric==='cumulative'?cum:state.metric==='win'?(r.rounds?r.wins/r.rounds*100:null):r.rounds;if(r.status==='empty'&&state.metric!=='rounds')value=null;return {...r,value,cumulative:cum};});}
function ticks(values){if(state.metric==='win')return [0,20,40,60,80,100];const good=values.filter(v=>v!=null),min=Math.min(0,...good),max=Math.max(0,...good);if(min===0&&max===0)return state.metric==='rounds'?[0,1,2]:[-1,0,1];let raw=(max-min)/5,pow=10**Math.floor(Math.log10(raw)),step=[1,2,2.5,5,10].map(n=>n*pow).find(n=>n>=raw);if(state.metric==='rounds')step=Math.max(1,Math.ceil(step));while(Math.ceil(max/step)-Math.floor(min/step)>6)step*=2;const out=[];for(let i=Math.floor(min/step);i<=Math.ceil(max/step);i++)out.push(Number((i*step).toPrecision(12)));return out;}
function unit(){return state.metric==='win'?'%':state.metric==='rounds'?'回合':'CNY';}
function label(v,full=false){if(v==null)return'—';if(state.metric==='win')return v.toFixed(full?1:0)+'%';if(state.metric==='rounds')return String(v);return full?signed(v):Math.abs(v)>=1e8?(v/1e8).toFixed(2)+'亿':Math.abs(v)>=1e4?(v/1e4).toFixed(2)+'万':String(v);}
function periodLabel(){return /^\d{4}$/.test(state.year)?'每月净盈亏':'每年净盈亏';}
function updateCopy(rs){const yr=$('#year-select');yr.value=state.year;const yw=yr.closest('.custom-select');if(yw&&yw.querySelector('.custom-select-label')){const txt=yr.options[yr.selectedIndex].text;yw.querySelector('.custom-select-label').textContent=txt;yw.querySelector('.custom-select-trigger').setAttribute('aria-label','历史范围：'+txt);yw.querySelectorAll('.custom-select-option').forEach((o,i)=>o.setAttribute('aria-selected',String(i===yr.selectedIndex)));}const unknown=rs.some(r=>r.status==='missing'),valid=rs.filter(r=>r.status!=='future'),sum=k=>unknown?null:valid.reduce((n,r)=>n+r[k],0),net=sum('net'),rounds=sum('rounds'),wins=sum('wins');$('#range-caption').textContent=`按平仓时间 · ${state.year==='all'?'全部历史':state.year.replace('-','–')}`;$('#chart-title').textContent=state.metric==='net'?periodLabel():state.metric==='cumulative'?'累计净盈亏':state.metric==='win'?'各期胜率':'各期回合数';$('#unit-label').textContent=unit();$('#kpi-net').textContent=compact(net);$('#kpi-net').title=signed(net)+' CNY';$('#kpi-net').className=net>0?'positive':net<0?'negative':'';$('#kpi-rounds').textContent=rounds??'—';$('#kpi-win').textContent=rounds?(wins/rounds*100).toFixed(1)+'%':'—';$('#kpi-win-denom').textContent=rounds==null?'— / —':`${wins} / ${rounds}`;$('#kpi-fees').textContent=compact(sum('fees')).replace(/^\+/,'');$('#kpi-fees').title=amount(sum('fees'))+' CNY';
const select=$('#metric-select');select.options[0].text=periodLabel();const wrap=select.closest('.custom-select');if(wrap){const option=wrap.querySelector('.custom-select-option');if(option)option.textContent=periodLabel();if(state.metric==='net'){const text=wrap.querySelector('.custom-select-label');if(text)text.textContent=periodLabel();const trigger=wrap.querySelector('.custom-select-trigger');if(trigger)trigger.setAttribute('aria-label','历史指标：'+periodLabel());}}}
function render(){const rs=rows(),d=series(rs),W=svg.clientWidth,H=354,L=70,R=24,T=24,B=44,pw=W-L-R,ph=H-T-B,ts=ticks(d.map(r=>r.value)),lo=ts[0],hi=ts.at(-1),x=i=>L+(d.length===1?pw/2:i*pw/(d.length-1)),y=v=>T+(hi-v)/(hi-lo||1)*ph;geom={x,y,L,R,T,B,W,H,pw,ph,d};svg.setAttribute('viewBox',`0 0 ${W} ${H}`);let h='';d.forEach((r,i)=>{if(!r.status)return;const a=i===0?L:(x(i-1)+x(i))/2,b=i===d.length-1?W-R:(x(i)+x(i+1))/2;h+=`<rect class="state-zone ${r.status}" x="${a}" y="${T}" width="${b-a}" height="${ph}"/>`;});ts.forEach(v=>{h+=`<line class="${v===0?'zero':'grid'}" x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}"/><text class="tick-label" x="${L-10}" y="${y(v)+4}" text-anchor="end">${label(v)}</text>`;});let path=[];function flush(){if(path.length)h+=`<polyline class="series" points="${path.join(' ')}"/>`;path=[];}d.forEach((r,i)=>{if(r.value==null)flush();else path.push(`${x(i)},${y(r.value)}`)});flush();d.forEach((r,i)=>{h+=`<text class="x-label tick-label" x="${x(i)}" y="${H-16}">${r.date.length>4?r.date.slice(5)+'月':r.date}</text>`;if(r.value!=null)h+=`<circle class="chart-point${r.value===0?' is-zero':''}" cx="${x(i)}" cy="${y(r.value)}" r="3"/>`;const a=i===0?L:(x(i-1)+x(i))/2,b=i===d.length-1?W-R:(x(i)+x(i+1))/2;h+=`<rect class="chart-hit" role="button" tabindex="0" data-index="${i}" aria-label="${r.date} ${reason(r)||label(r.value,true)}" x="${a}" y="${T}" width="${b-a}" height="${ph}"/>`;});h+='<g id="overlay" aria-hidden="true"></g>';svg.innerHTML=h;for(const hit of svg.querySelectorAll('.chart-hit')){hit.addEventListener('mouseenter',()=>{if(!state.fixed)show(+hit.dataset.index)});hit.addEventListener('focus',()=>show(+hit.dataset.index));hit.addEventListener('click',()=>{show(+hit.dataset.index);state.fixed=true;});hit.addEventListener('keydown',e=>key(e,+hit.dataset.index));}state.hover=null;state.fixed=false;tip.hidden=true;updateCopy(rs);}
function reason(r){return r.status==='future'?'未来月份，尚无可统计的已平仓交易':r.status==='empty'?'该范围没有已平仓回合':r.status==='missing'?'该期源数据缺失，不能视为零':r.cumulative==null?'前期数据缺失，累计金额暂不可计算':'';}
function show(i){state.hover=i;const {d,x,y,L,W,T,ph}=geom,r=d[i],g=$('#overlay');g.innerHTML=`<line class="crosshair" x1="${x(i)}" x2="${x(i)}" y1="${T}" y2="${T+ph}"/>`+(r.value==null?'':`<line class="crosshair" x1="${L}" x2="${W-24}" y1="${y(r.value)}" y2="${y(r.value)}"/>`);tip.innerHTML=`<strong>${r.date} · ${unit()}</strong><br>${state.metric==='cumulative'?'累计读数':'当期读数'}：${label(r.value,true)}<br>当期净盈亏：${signed(r.net)} CNY<br>累计净盈亏：${signed(r.cumulative)} CNY<br>盈利 / 全部回合：${r.wins??'—'} / ${r.rounds??'—'}<br><span class="muted">${reason(r)||'费用已扣除'}</span>`;tip.hidden=false;const w=tip.offsetWidth,h=tip.offsetHeight,anchor=r.value==null?T+ph/2:y(r.value);tip.style.left=Math.max(4,Math.min(W-w-4,x(i)+(x(i)+w+16>W?-w-12:12)))+'px';tip.style.top=Math.max(4,Math.min(354-h-4,anchor+12))+'px';}
function key(e,i){let next=i;if(e.key==='ArrowRight')next=Math.min(geom.d.length-1,i+1);else if(e.key==='ArrowLeft')next=Math.max(0,i-1);else if(e.key==='Home')next=0;else if(e.key==='End')next=geom.d.length-1;else if(e.key==='Enter'||e.key===' '){e.preventDefault();state.fixed=!state.fixed;show(i);return;}else if(e.key==='Escape'){e.preventDefault();clearTip();return;}else return;e.preventDefault();svg.querySelector(`[data-index="${next}"]`).focus();}
function clearTip(){state.hover=null;state.fixed=false;tip.hidden=true;$('#overlay').innerHTML='';}
function status(text,kind=''){ $('#status-text').textContent=text;$('#status-note').dataset.kind=kind;$('#retry').hidden=kind!=='error';}
function rangeName(v){return v==='all'?'全部历史':v.replace('-','–');}
function requestRange(){clearTimeout(timer);if(state.fixture==='failed'){status(`读取 ${rangeName(state.pending)} 失败；仍显示 ${rangeName(state.year)}。`,'error');$('#year-select').value=state.year;return;}status(`正在读取 ${rangeName(state.pending)}；保留原范围和数据。`,'loading');timer=setTimeout(()=>{state.year=state.pending;state.fixture='normal';$('#state-select').value='normal';status('');render();},600);}
$('#year-select').addEventListener('change',e=>{state.pending=e.target.value;requestRange();});$('#metric-select').addEventListener('change',e=>{state.metric=e.target.value;render();});$('#state-select').addEventListener('change',e=>{clearTimeout(timer);state.fixture=e.target.value;if(state.fixture==='loading'){requestRange();return;}if(state.fixture==='failed'){status(`读取失败；保留 ${rangeName(state.year)} 的数据，可选择新范围后重试。`,'error');return;}status('');render();});$('#retry').addEventListener('click',()=>{state.fixture='normal';requestRange();});$('#chart-wrap').addEventListener('mouseleave',()=>{if(!state.fixed)clearTip();});svg.addEventListener('focusout',e=>{if(!svg.contains(e.relatedTarget)&&!state.fixed)clearTip();});window.addEventListener('resize',render);render();
})();
